\begin{enumerate}\renewcommand{\labelenumi}{\roman{enumi}.}
\item Find conditions on $a,b,c\in\mathbb R$ so that $v=(a,b,c)\in\mathbb R^3$ belongs to\[W=\mathit{span}((1,2,0),(-1,1,2),(3,0,-4)).\] 
\item Let $U$ and $W$ be two subspaces of a vector space $V$. Show that $U+W$ is the smallest subspace containing $U$ and $W$. Hence show that $U+W=L(U\cup W)$. 
\item Determine whether the vectors $(1,2,-3,1),(3,7,1,-2),(1,3,7,-4)$ in $\mathbb R^4$ are linearly dependent or independent. 
\end{enumerate}
